namespace RonSijm.FluidHumidifier.Factories.EVS;

public class InnerEnvironmentInitialVlansFactory(Action<Humidifier.EVS.EnvironmentTypes.InitialVlans> factoryAction = null) : SubResourceFactory<Humidifier.EVS.EnvironmentTypes.InitialVlans>
{

    internal InnerEnvironmentInitialVlanInfoFactory VmkManagementFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory VTepFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory ExpansionVlan2Factory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory VSanFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory VMotionFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory HcxFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory EdgeVTepFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory ExpansionVlan1Factory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory VmManagementFactory { get; set; }

    internal InnerEnvironmentInitialVlanInfoFactory NsxUpLinkFactory { get; set; }

    protected override Humidifier.EVS.EnvironmentTypes.InitialVlans Create()
    {
        var initialVlansResult = CreateInitialVlans();
        factoryAction?.Invoke(initialVlansResult);

        return initialVlansResult;
    }

    private Humidifier.EVS.EnvironmentTypes.InitialVlans CreateInitialVlans()
    {
        var initialVlansResult = new Humidifier.EVS.EnvironmentTypes.InitialVlans();

        return initialVlansResult;
    }
    public override void CreateChildren(Humidifier.EVS.EnvironmentTypes.InitialVlans result)
    {
        base.CreateChildren(result);

        result.VmkManagement ??= VmkManagementFactory?.Build();
        result.VTep ??= VTepFactory?.Build();
        result.ExpansionVlan2 ??= ExpansionVlan2Factory?.Build();
        result.VSan ??= VSanFactory?.Build();
        result.VMotion ??= VMotionFactory?.Build();
        result.Hcx ??= HcxFactory?.Build();
        result.EdgeVTep ??= EdgeVTepFactory?.Build();
        result.ExpansionVlan1 ??= ExpansionVlan1Factory?.Build();
        result.VmManagement ??= VmManagementFactory?.Build();
        result.NsxUpLink ??= NsxUpLinkFactory?.Build();
    }

} // End Of Class

